/* ============================================================================
   PLAN_DESARROLLO_1  (27/10/2026)  marca PL_DES_V1
   ----------------------------------------------------------------------------
   1. Tabla nueva VCT_ACCIONES_DESARROLLO (desarrollo de las acciones del plan:
      visita, consultor, realizado / planificado, horas, titulo, desarrollo, proximo paso).
   2. Parche sobre la definicion VIVA de dbo.VCT_MAIN_PROYECTO_V360:
      - Desarrollo de acciones: comandos PV_PL_DES_GUARDAR / PV_PL_DES_BORRAR, horas validadas
        contra la visita del consultor (no suman a las horas ejecutadas), historial de la accion.
      - Arbol del plan: columna "Horas dev." en capitulo / item / subitem, horas en el detalle,
        accion sin tilde de cumplida, con su desarrollo desplegable y "Cargar desarrollo".
      - Accion del plan: inicio obligatorio, dentro del rango de su item o subitem, nace Pendiente.
      - Carga del plan: opcion "Subir Excel" (PV_PL_IMPORTAR) y "Eliminar plan" (PV_PL_BORRAR)
        mientras la accion "Carga del plan" no este cumplida y no haya desarrollo cargado.
      - Tiempo transcurrido desde la primera visita del proyecto (Plan y Resumen).
      - Agenda: "Trabajo de la visita" (lista y clic en el calendario); no se borra una visita con desarrollo.
      - Assets: vct-proyecto-v360.css ?v=41 y vct-proyecto-v360.js ?v=33 (subir los dos archivos).
   Si alguno de los puntos del parche no se encuentra en la definicion vigente, NO se cambia nada.
   Re-ejecutable: si la marca PL_DES_V1 ya esta, avisa y no hace nada.
   SSMS: F5.
   ============================================================================ */
USE [MuhlePROD];
SET NOCOUNT ON;
GO

/* ---------- 1. tabla de desarrollo de las acciones ---------- */
IF OBJECT_ID('dbo.VCT_ACCIONES_DESARROLLO', 'U') IS NULL
BEGIN
    CREATE TABLE dbo.VCT_ACCIONES_DESARROLLO (
        ID            INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_VCT_ACCIONES_DESARROLLO PRIMARY KEY,
        ID_ACCION     INT NOT NULL,
        ID_VISITA     INT NOT NULL,
        ID_CONSULTOR  INT NOT NULL,
        TIPO          VARCHAR(12) NOT NULL CONSTRAINT CK_VCT_ACC_DES_TIPO CHECK (TIPO IN ('REALIZADO','PLANIFICADO')),
        HORAS         DECIMAL(5,2) NULL CONSTRAINT CK_VCT_ACC_DES_HORAS CHECK (HORAS IS NULL OR HORAS > 0),
        TITULO        VARCHAR(300) NOT NULL,
        DESARROLLO    VARCHAR(MAX) NULL,
        PROXIMO_PASO  VARCHAR(1000) NULL,
        FECHA_ALTA    DATETIME NOT NULL CONSTRAINT DF_VCT_ACC_DES_FALTA DEFAULT GETDATE(),
        USUARIO_ALTA  VARCHAR(100) NULL,
        FECHA_UPD     DATETIME NULL,
        USUARIO_UPD   VARCHAR(100) NULL
    );
    CREATE INDEX IX_VCT_ACC_DES_ACCION ON dbo.VCT_ACCIONES_DESARROLLO (ID_ACCION);
    CREATE INDEX IX_VCT_ACC_DES_VISITA ON dbo.VCT_ACCIONES_DESARROLLO (ID_VISITA, ID_CONSULTOR);
    PRINT 'OK   tabla VCT_ACCIONES_DESARROLLO creada.';
END
ELSE PRINT 'OK   la tabla VCT_ACCIONES_DESARROLLO ya existia.';
GO
/* claves foraneas (solo si la tabla referenciada tiene clave en ID; si no, avisa y sigue) */
DECLARE @FK TABLE (N SYSNAME, COL SYSNAME, REF SYSNAME);
INSERT INTO @FK VALUES ('FK_VCT_ACC_DES_ACCION', 'ID_ACCION', 'VCT_ACCIONES'),
                       ('FK_VCT_ACC_DES_VISITA', 'ID_VISITA', 'VCT_PROYECTOS_VISITAS'),
                       ('FK_VCT_ACC_DES_CONSULTOR', 'ID_CONSULTOR', 'VCT_CONSULTORES');
DECLARE @FN SYSNAME, @FC SYSNAME, @FR SYSNAME, @FS NVARCHAR(1000);
WHILE EXISTS (SELECT 1 FROM @FK)
BEGIN
    SELECT TOP 1 @FN = N, @FC = COL, @FR = REF FROM @FK ORDER BY N;
    DELETE FROM @FK WHERE N = @FN;
    IF OBJECT_ID('dbo.' + @FN, 'F') IS NOT NULL CONTINUE;
    SET @FS = N'ALTER TABLE dbo.VCT_ACCIONES_DESARROLLO WITH CHECK ADD CONSTRAINT ' + QUOTENAME(@FN) + N' FOREIGN KEY (' + QUOTENAME(@FC) + N') REFERENCES dbo.' + QUOTENAME(@FR) + N' (ID);';
    BEGIN TRY
        EXEC sys.sp_executesql @FS;
        PRINT 'OK   ' + @FN + '.';
    END TRY
    BEGIN CATCH
        PRINT 'AVISO ' + @FN + ' no se pudo crear (' + ERROR_MESSAGE() + '). La tabla funciona igual.';
    END CATCH;
END;
GO

/* ---------- 2. parche de dbo.VCT_MAIN_PROYECTO_V360 ---------- */
DECLARE @D NVARCHAR(MAX) = OBJECT_DEFINITION(OBJECT_ID('dbo.VCT_MAIN_PROYECTO_V360')),
        @NE NVARCHAR(MAX), @RE NVARCHAR(MAX), @N INT, @F NVARCHAR(MAX) = N'', @s INT, @p INT;
IF @D IS NULL
    PRINT 'FALLO: no se encontro dbo.VCT_MAIN_PROYECTO_V360.';
ELSE IF CHARINDEX(N'PL_DES_V1', @D) > 0
    PRINT 'OK   el parche PL_DES_V1 ya estaba aplicado: no se hizo nada.';
ELSE
BEGIN
    SET @D = REPLACE(@D, NCHAR(13) + NCHAR(10), NCHAR(10));
    /* assets */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'vct-proyecto-v360.css?v=40"><script src="../js/vct-proyecto-v360.js?v=32"';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'vct-proyecto-v360.css?v=41"><script src="../js/vct-proyecto-v360.js?v=33"';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' assets(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* cmds */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'IF @B_FLAG = ''1'' AND @B_CMD IN (''PV_PL_GENERAR'',''PV_PL_ITEM_GUARDAR'',''PV_PL_ITEM_BORRAR'',''PV_PL_ACC_GUARDAR'',''PV_PL_ACC_ESTADO'',''PV_PL_ACC_BORRAR'',''PV_PL_CERRAR'')';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'/* PL_DES_V1: + PV_PL_IMPORTAR (plan desde Excel), PV_PL_BORRAR (eliminar el plan antes de Finalizar carga),' + NCHAR(10) + N'       PV_PL_DES_GUARDAR / PV_PL_DES_BORRAR (desarrollo de las acciones del plan, VCT_ACCIONES_DESARROLLO) */' + NCHAR(10) + N'    IF @B_FLAG = ''1'' AND @B_CMD IN (''PV_PL_GENERAR'',''PV_PL_ITEM_GUARDAR'',''PV_PL_ITEM_BORRAR'',''PV_PL_ACC_GUARDAR'',''PV_PL_ACC_ESTADO'',''PV_PL_ACC_BORRAR'',''PV_PL_CERRAR'',''PV_PL_IMPORTAR'',''PV_PL_BORRAR'',''PV_PL_DES_GUARDAR'',''PV_PL_DES_BORRAR'')';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' cmds(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* decl */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'@PL_T19 VARCHAR(4000) = '''', @PL_T20 VARCHAR(4000) = '''', @PL_T21 VARCHAR(4000) = '''';';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'@PL_T19 VARCHAR(4000) = '''', @PL_T20 VARCHAR(4000) = '''', @PL_T21 VARCHAR(4000) = '''', @PL_RAW VARCHAR(MAX) = '''';';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' decl(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* sel */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'@PL_T21 = LTRIM(RTRIM(ISNULL(TEXTO21,'''')))';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'@PL_T21 = LTRIM(RTRIM(ISNULL(TEXTO21,''''))),' + NCHAR(10) + N'                     @PL_RAW = CONVERT(VARCHAR(MAX), ISNULL(TEXTO11,'''')) + ISNULL(TEXTO12,'''') + ISNULL(TEXTO13,'''') + ISNULL(TEXTO14,'''') + ISNULL(TEXTO15,'''') + ISNULL(TEXTO16,'''') + ISNULL(TEXTO17,'''') + ISNULL(TEXTO18,'''') + ISNULL(TEXTO19,'''') + ISNULL(TEXTO20,'''') + ISNULL(TEXTO21,'''') + ISNULL(TEXTO22,'''')';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' sel(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* volver */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'SET @VOLVER = ''plan'';';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'SET @VOLVER = ''plan'';' + NCHAR(10) + N'        UPDATE dbo.VCT_BUFFER SET TEXTO22 = NULL WHERE PAR_KEY = @IPKEYJOB;';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' volver(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* noplan */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'IF @ERR = '''' AND @B_CMD <> ''PV_PL_GENERAR'' AND @PL_PLAN IS NULL';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'IF @ERR = '''' AND @B_CMD NOT IN (''PV_PL_GENERAR'',''PV_PL_IMPORTAR'') AND @PL_PLAN IS NULL';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' noplan(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* gen */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'IF @ERR = '''' AND @B_CMD = ''PV_PL_GENERAR''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'IF @ERR = '''' AND @B_CMD IN (''PV_PL_GENERAR'',''PV_PL_IMPORTAR'')';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' gen(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* blanco */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'@PL_DOC IS NULL AND UPPER(@B_T11) = ''BLANCO''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'@PL_DOC IS NULL AND (UPPER(@B_T11) = ''BLANCO'' OR @B_CMD = ''PV_PL_IMPORTAR'')';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 2 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' blanco(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* acc_ini */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'ELSE IF @PL_FI IS NULL SET @ERR = ''Vence es obligatorio.'';';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'ELSE IF @PL_FF IS NULL SET @ERR = ''Fecha inicio es obligatoria.'';' + NCHAR(10) + N'                ELSE IF @PL_FI IS NULL SET @ERR = ''Vence es obligatorio.'';';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' acc_ini(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* acc_rango */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'SELECT @PL_TOP_FI = FECHA_INICIO, @PL_TOP_FF = FECHA_VENCIMIENTO FROM dbo.VCT_PROYECTOS_PLAN_ITEMS WITH(NOLOCK) WHERE ID = @PL_TOP;';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'SELECT @PL_TOP_FI = FECHA_INICIO, @PL_TOP_FF = FECHA_VENCIMIENTO FROM dbo.VCT_PROYECTOS_PLAN_ITEMS WITH(NOLOCK) WHERE ID = @PL_TOP;' + NCHAR(10) + N'            /* PL_DES_V1: rango del propio subitem si tiene fechas */' + NCHAR(10) + N'            SELECT @PL_TOP_FI = ISNULL(FECHA_INICIO, @PL_TOP_FI), @PL_TOP_FF = ISNULL(FECHA_VENCIMIENTO, @PL_TOP_FF) FROM dbo.VCT_PROYECTOS_PLAN_ITEMS WITH(NOLOCK) WHERE ID = @PL_ID AND ID <> @PL_TOP;';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' acc_rango(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* acc_pend */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'IF @ERR = '''' AND ISNULL(@PA_EST_FIN, 0) = 0 SET @PA_RES = NULL;';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'IF @ERR = '''' AND ISNULL(@PA_EST_FIN, 0) = 0 SET @PA_RES = NULL;' + NCHAR(10) + N'                IF @ERR = '''' AND @PA_ACC IS NULL SELECT @PA_EST = @PL_PEND, @PA_EST_FIN = 0, @PA_RES = NULL;   /* PL_DES_V1: la accion nace Pendiente */';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' acc_pend(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* sub_fi */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'FECHA_INICIO = CASE WHEN @PL_ES_SUB = 1 THEN NULL ELSE @PL_FI END,';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'FECHA_INICIO = CASE WHEN @PL_ES_SUB = 1 THEN FECHA_INICIO ELSE @PL_FI END,';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' sub_fi(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* sub_ff */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'FECHA_VENCIMIENTO = CASE WHEN @PL_ES_SUB = 1 THEN NULL ELSE @PL_FF END,';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'FECHA_VENCIMIENTO = CASE WHEN @PL_ES_SUB = 1 THEN FECHA_VENCIMIENTO ELSE @PL_FF END,';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' sub_ff(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* valid */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'IF @ERR = '''' AND @B_CMD = ''PV_PL_CERRAR''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'/* ===== PL_DES_V1: plan desde Excel (PV_PL_IMPORTAR), eliminar plan (PV_PL_BORRAR), desarrollo (PV_PL_DES_*) ===== */' + NCHAR(10) + N'        DECLARE @IX TABLE (ORD INT, COD VARCHAR(60), TIT VARCHAR(400), D1 VARCHAR(30), D2 VARCHAR(30), FI DATETIME, FF DATETIME, NIV INT, PAD VARCHAR(60), ID INT);' + NCHAR(10) + N'        DECLARE @IX_P INT, @IX_L VARCHAR(4000), @IX_N INT = 0, @IX_C1 VARCHAR(4000), @IX_C2 VARCHAR(4000), @IX_C3 VARCHAR(4000), @IX_C4 VARCHAR(4000), @IX_Q INT;' + NCHAR(10) + N'        DECLARE @DS_ID INT, @DS_ACC INT, @DS_EST INT, @DS_VIS INT, @DS_CONS INT, @DS_TIPO VARCHAR(12) = '''', @DS_HRS NUMERIC(9,2), @DS_VH NUMERIC(18,2),' + NCHAR(10) + N'                @DS_USADAS NUMERIC(18,2) = 0, @DS_VDES DATETIME, @DS_VEST VARCHAR(50), @DS_OLD_ACC INT, @DS_Q INT, @DS_H VARCHAR(50);' + NCHAR(10) + N'        IF @ERR = '''' AND @B_CMD = ''PV_PL_IMPORTAR''' + NCHAR(10) + N'        BEGIN' + NCHAR(10) + N'            /* filas "codigo TAB titulo TAB desde TAB hasta" (aaaa-mm-dd) separadas por salto de linea, en TEXTO11..TEXTO22 */' + NCHAR(10) + N'            SET @PL_RAW = REPLACE(@PL_RAW, CHAR(13), '''');' + NCHAR(10) + N'            WHILE DATALENGTH(@PL_RAW) > 0 AND @IX_N < 3000' + NCHAR(10) + N'            BEGIN' + NCHAR(10) + N'                SET @IX_P = CHARINDEX(CHAR(10), @PL_RAW);' + NCHAR(10) + N'                IF @IX_P = 0 SET @IX_P = DATALENGTH(@PL_RAW) + 1;' + NCHAR(10) + N'                SET @IX_L = LEFT(SUBSTRING(@PL_RAW, 1, @IX_P - 1), 3990) + CHAR(9) + CHAR(9) + CHAR(9);' + NCHAR(10) + N'                SET @PL_RAW = SUBSTRING(@PL_RAW, @IX_P + 1, 2147483647);' + NCHAR(10) + N'                SET @IX_N = @IX_N + 1;' + NCHAR(10) + N'                SET @IX_Q = CHARINDEX(CHAR(9), @IX_L);' + NCHAR(10) + N'                SET @IX_C1 = LEFT(@IX_L, @IX_Q - 1);' + NCHAR(10) + N'                SET @IX_L = SUBSTRING(@IX_L, @IX_Q + 1, 4000);' + NCHAR(10) + N'                SET @IX_Q = CHARINDEX(CHAR(9), @IX_L);' + NCHAR(10) + N'                SET @IX_C2 = LEFT(@IX_L, @IX_Q - 1);' + NCHAR(10) + N'                SET @IX_L = SUBSTRING(@IX_L, @IX_Q + 1, 4000);' + NCHAR(10) + N'                SET @IX_Q = CHARINDEX(CHAR(9), @IX_L);' + NCHAR(10) + N'                SET @IX_C3 = LEFT(@IX_L, @IX_Q - 1);' + NCHAR(10) + N'                SET @IX_L = SUBSTRING(@IX_L, @IX_Q + 1, 4000) + CHAR(9);' + NCHAR(10) + N'                SET @IX_Q = CHARINDEX(CHAR(9), @IX_L);' + NCHAR(10) + N'                SET @IX_C4 = LEFT(@IX_L, @IX_Q - 1);' + NCHAR(10) + N'                IF LTRIM(RTRIM(@IX_C1)) <> '''' OR LTRIM(RTRIM(@IX_C2)) <> ''''' + NCHAR(10) + N'                    INSERT INTO @IX (ORD, COD, TIT, D1, D2)' + NCHAR(10) + N'                    VALUES (@IX_N, LEFT(LTRIM(RTRIM(@IX_C1)), 60), LEFT(LTRIM(RTRIM(@IX_C2)), 400), LEFT(LTRIM(RTRIM(@IX_C3)), 30), LEFT(LTRIM(RTRIM(@IX_C4)), 30));' + NCHAR(10) + N'            END;' + NCHAR(10) + N'            UPDATE @IX SET COD = LEFT(COD, LEN(COD) - 1) WHERE RIGHT(COD, 1) = ''.'' AND LEN(COD) > 1;' + NCHAR(10) + N'            UPDATE @IX SET NIV = LEN(COD) - LEN(REPLACE(COD, ''.'', '''')) + 1,' + NCHAR(10) + N'                           PAD = CASE WHEN CHARINDEX(''.'', COD) > 0 THEN LEFT(COD, LEN(COD) - CHARINDEX(''.'', REVERSE(COD))) ELSE '''' END,' + NCHAR(10) + N'                           FI = CASE WHEN D1 LIKE ''[12][0-9][0-9][0-9]-[01][0-9]-[0-3][0-9]'' AND ISDATE(REPLACE(D1,''-'','''')) = 1 THEN CONVERT(DATETIME, REPLACE(D1,''-'',''''), 112) END,' + NCHAR(10) + N'                           FF = CASE WHEN D2 LIKE ''[12][0-9][0-9][0-9]-[01][0-9]-[0-3][0-9]'' AND ISDATE(REPLACE(D2,''-'','''')) = 1 THEN CONVERT(DATETIME, REPLACE(D2,''-'',''''), 112) END;' + NCHAR(10) + N'            IF NOT EXISTS (SELECT 1 FROM @IX) SET @ERR = ''El archivo no tiene filas para cargar.'';' + NCHAR(10) + N'            IF @ERR = '''' SELECT TOP 1 @ERR = ''C'' + CHAR(243) + ''digo "'' + COD + ''" no v'' + CHAR(225) + ''lido: use 4 (cap'' + CHAR(237) + ''tulo), 4.1 ('' + CHAR(237) + ''tem) o 4.1.1 (sub'' + CHAR(237) + ''tem).''' + NCHAR(10) + N'                         FROM @IX WHERE COD = '''' OR COD LIKE ''%[^0-9.]%'' OR COD LIKE ''.%'' OR COD LIKE ''%..%'' OR NIV > 3 ORDER BY ORD;' + NCHAR(10) + N'            IF @ERR = '''' SELECT TOP 1 @ERR = ''C'' + CHAR(243) + ''digo '' + COD + '': falta el t'' + CHAR(237) + ''tulo.'' FROM @IX WHERE TIT = '''' ORDER BY ORD;' + NCHAR(10) + N'            IF @ERR = '''' SELECT TOP 1 @ERR = ''El c'' + CHAR(243) + ''digo '' + X.COD + '' est'' + CHAR(225) + '' repetido.'' FROM @IX X WHERE (SELECT COUNT(*) FROM @IX Y WHERE Y.COD = X.COD) > 1 ORDER BY X.ORD;' + NCHAR(10) + N'            IF @ERR = '''' SELECT TOP 1 @ERR = ''El sub'' + CHAR(237) + ''tem '' + X.COD + '' no tiene su '' + CHAR(237) + ''tem '' + X.PAD + '' en el archivo.''' + NCHAR(10) + N'                         FROM @IX X WHERE X.NIV = 3 AND NOT EXISTS (SELECT 1 FROM @IX Y WHERE Y.COD = X.PAD AND Y.NIV = 2) ORDER BY X.ORD;' + NCHAR(10) + N'            IF @ERR = '''' SELECT TOP 1 @ERR = ''C'' + CHAR(243) + ''digo '' + COD + '': la fecha '' + CASE WHEN D1 <> '''' AND FI IS NULL THEN ''desde'' ELSE ''hasta'' END + '' no es v'' + CHAR(225) + ''lida.''' + NCHAR(10) + N'                         FROM @IX WHERE NIV > 1 AND ((D1 <> '''' AND FI IS NULL) OR (D2 <> '''' AND FF IS NULL)) ORDER BY ORD;' + NCHAR(10) + N'            IF @ERR = '''' SELECT TOP 1 @ERR = ''C'' + CHAR(243) + ''digo '' + COD + '': la fecha hasta es anterior a la fecha desde.'' FROM @IX WHERE NIV > 1 AND FF < FI ORDER BY ORD;' + NCHAR(10) + N'            IF @ERR = '''' SELECT TOP 1 @ERR = ''C'' + CHAR(243) + ''digo '' + COD + '': las fechas tienen que estar dentro del proyecto (''' + NCHAR(10) + N'                                           + ISNULL(CONVERT(VARCHAR(10), @PL_P_INI, 103), ''-'') + '' - '' + ISNULL(CONVERT(VARCHAR(10), @PL_P_FIN, 103), ''-'') + '').''' + NCHAR(10) + N'                         FROM @IX WHERE NIV > 1 AND ((@PL_P_INI IS NOT NULL AND FI < CONVERT(DATE, @PL_P_INI)) OR (@PL_P_FIN IS NOT NULL AND FF > @PL_P_FIN)) ORDER BY ORD;' + NCHAR(10) + N'            IF @ERR = '''' SELECT TOP 1 @ERR = ''Sub'' + CHAR(237) + ''tem '' + X.COD + '': las fechas tienen que estar dentro de las del '' + CHAR(237) + ''tem '' + Y.COD + ''.''' + NCHAR(10) + N'                         FROM @IX X INNER JOIN @IX Y ON Y.COD = X.PAD AND Y.NIV = 2' + NCHAR(10) + N'                         WHERE X.NIV = 3 AND ((X.FI IS NOT NULL AND Y.FI IS NOT NULL AND X.FI < Y.FI) OR (X.FF IS NOT NULL AND Y.FF IS NOT NULL AND X.FF > Y.FF)) ORDER BY X.ORD;' + NCHAR(10) + N'        END;' + NCHAR(10) + N'' + NCHAR(10) + N'        IF @ERR = '''' AND @B_CMD = ''PV_PL_BORRAR''' + NCHAR(10) + N'        BEGIN' + NCHAR(10) + N'            /* solo antes de "Finalizar carga" (accion CARGA_PLAN abierta) y sin desarrollo cargado */' + NCHAR(10) + N'            SELECT TOP 1 @PL_ACC = A.ID, @PL_ACC_EST = A.ID_ESTADO FROM dbo.VCT_ACCIONES A WITH(NOLOCK)' + NCHAR(10) + N'            INNER JOIN dbo.VCT_PRM_ACCIONES_SUBTIPOS ST WITH(NOLOCK) ON ST.ID = A.ID_SUBTIPO AND ST.CODIGO = ''CARGA_PLAN''' + NCHAR(10) + N'            INNER JOIN dbo.VCT_PRM_ACCIONES_ESTADOS E WITH(NOLOCK) ON E.ID = A.ID_ESTADO AND E.ES_FINAL = 0' + NCHAR(10) + N'            WHERE A.ID_PROYECTO = @ID_PROYECTO ORDER BY A.ID;' + NCHAR(10) + N'            IF @PL_ACC IS NULL SET @ERR = ''La carga del plan ya est'' + CHAR(225) + '' finalizada: el plan no se puede eliminar.''' + NCHAR(10) + N'            ELSE IF OBJECT_ID(''dbo.VCT_ACCIONES_DESARROLLO'', ''U'') IS NOT NULL' + NCHAR(10) + N'                 AND EXISTS (SELECT 1 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) INNER JOIN dbo.VCT_ACCIONES A WITH(NOLOCK) ON A.ID = D.ID_ACCION WHERE A.ID_PROYECTO = @ID_PROYECTO)' + NCHAR(10) + N'                SET @ERR = ''Hay acciones con desarrollo cargado: el plan no se puede eliminar.''' + NCHAR(10) + N'        END;' + NCHAR(10) + N'' + NCHAR(10) + N'        IF @ERR = '''' AND @B_CMD IN (''PV_PL_DES_GUARDAR'',''PV_PL_DES_BORRAR'') AND OBJECT_ID(''dbo.VCT_ACCIONES_DESARROLLO'', ''U'') IS NULL' + NCHAR(10) + N'            SET @ERR = ''Falta la tabla VCT_ACCIONES_DESARROLLO.'';' + NCHAR(10) + N'        IF @ERR = '''' AND @B_CMD IN (''PV_PL_DES_GUARDAR'',''PV_PL_DES_BORRAR'') AND @PL_ID IS NOT NULL' + NCHAR(10) + N'        BEGIN' + NCHAR(10) + N'            SET @DS_ID = @PL_ID;' + NCHAR(10) + N'            SELECT @DS_OLD_ACC = D.ID_ACCION FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'            INNER JOIN dbo.VCT_ACCIONES A WITH(NOLOCK) ON A.ID = D.ID_ACCION AND A.ID_PROYECTO = @ID_PROYECTO' + NCHAR(10) + N'            WHERE D.ID = @DS_ID;' + NCHAR(10) + N'            IF @DS_OLD_ACC IS NULL SET @ERR = ''El desarrollo no es de este proyecto.'';' + NCHAR(10) + N'        END;' + NCHAR(10) + N'        IF @ERR = '''' AND @B_CMD = ''PV_PL_DES_BORRAR'' AND @DS_ID IS NULL SET @ERR = ''Falta el desarrollo a eliminar.'';' + NCHAR(10) + N'        IF @ERR = '''' AND @B_CMD = ''PV_PL_DES_GUARDAR''' + NCHAR(10) + N'        BEGIN' + NCHAR(10) + N'            /* TEXTO11 accion, TEXTO12 tipo R / P, TEXTO13 "visita:consultor", TEXTO14 horas, TEXTO15 titulo, TEXTO16 desarrollo, TEXTO17 proximo paso */' + NCHAR(10) + N'            IF @B_T11 <> '''' AND PATINDEX(''%[^0-9]%'', @B_T11) = 0 AND LEN(@B_T11) <= 9' + NCHAR(10) + N'                SELECT @DS_ACC = A.ID, @DS_EST = A.ID_ESTADO FROM dbo.VCT_ACCIONES A WITH(NOLOCK)' + NCHAR(10) + N'                WHERE A.ID = CONVERT(INT, @B_T11) AND A.ID_PROYECTO = @ID_PROYECTO AND A.ID_PLAN_ITEM IS NOT NULL;' + NCHAR(10) + N'            SET @DS_TIPO = CASE UPPER(@B_T12) WHEN ''R'' THEN ''REALIZADO'' WHEN ''P'' THEN ''PLANIFICADO'' ELSE '''' END;' + NCHAR(10) + N'            SET @DS_Q = CHARINDEX('':'', @B_T13);' + NCHAR(10) + N'            IF @DS_Q BETWEEN 2 AND 10 AND LEN(@B_T13) - @DS_Q BETWEEN 1 AND 9' + NCHAR(10) + N'               AND PATINDEX(''%[^0-9]%'', LEFT(@B_T13, @DS_Q - 1)) = 0 AND PATINDEX(''%[^0-9]%'', SUBSTRING(@B_T13, @DS_Q + 1, 20)) = 0' + NCHAR(10) + N'                SELECT TOP 1 @DS_VIS = V.ID, @DS_CONS = VC.ID_CONSULTOR, @DS_VH = ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)),' + NCHAR(10) + N'                       @DS_VDES = V.FECHA_DESDE, @DS_VEST = UPPER(LTRIM(RTRIM(ISNULL(V.ESTADO,''''))))' + NCHAR(10) + N'                FROM dbo.VCT_PROYECTOS_VISITAS V WITH(NOLOCK)' + NCHAR(10) + N'                INNER JOIN dbo.VCT_PROYECTOS_VISITAS_CONSULTORES VC WITH(NOLOCK) ON VC.ID_VISITA = V.ID' + NCHAR(10) + N'                WHERE V.ID = CONVERT(INT, LEFT(@B_T13, @DS_Q - 1)) AND VC.ID_CONSULTOR = CONVERT(INT, SUBSTRING(@B_T13, @DS_Q + 1, 20))' + NCHAR(10) + N'                  AND V.ID_PROYECTO = @ID_PROYECTO AND UPPER(LTRIM(RTRIM(ISNULL(V.ESTADO,'''')))) NOT IN (''CANCELADO'',''ANULADO'');' + NCHAR(10) + N'            SET @DS_H = REPLACE(@PL_T14, '','', ''.'');' + NCHAR(10) + N'            IF @DS_H <> '''' AND @DS_H <> ''.'' AND PATINDEX(''%[^0-9.]%'', @DS_H) = 0 AND @DS_H NOT LIKE ''%.%.%'' AND LEN(@DS_H) <= 6' + NCHAR(10) + N'                SET @DS_HRS = CONVERT(NUMERIC(9,2), @DS_H);' + NCHAR(10) + N'            IF @DS_ACC IS NULL SET @ERR = ''La acci'' + CHAR(243) + ''n no es del plan de este proyecto.''' + NCHAR(10) + N'            ELSE IF @DS_TIPO = '''' SET @ERR = ''Tipo es obligatorio.''' + NCHAR(10) + N'            ELSE IF @DS_VIS IS NULL SET @ERR = ''Visita es obligatoria: elija una visita de la agenda del proyecto.''' + NCHAR(10) + N'            ELSE IF @DS_TIPO = ''REALIZADO'' AND (@DS_VEST <> ''CONFIRMADO'' OR CONVERT(DATE, @DS_VDES) > CONVERT(DATE, @HOY))' + NCHAR(10) + N'                SET @ERR = ''Un desarrollo realizado va en una visita confirmada de hoy o anterior.''' + NCHAR(10) + N'            ELSE IF @DS_TIPO = ''PLANIFICADO'' AND CONVERT(DATE, @DS_VDES) <= CONVERT(DATE, @HOY)' + NCHAR(10) + N'                SET @ERR = ''Un desarrollo planificado va en una visita futura.''' + NCHAR(10) + N'            ELSE IF @DS_TIPO = ''REALIZADO'' AND ISNULL(@DS_HRS, 0) <= 0 SET @ERR = ''Horas es obligatorio y debe ser mayor a cero.''' + NCHAR(10) + N'            ELSE IF @PL_T15 = '''' SET @ERR = ''T'' + CHAR(237) + ''tulo es obligatorio.''' + NCHAR(10) + N'            ELSE IF @DS_TIPO = ''REALIZADO'' AND @PL_T16 = '''' SET @ERR = ''Desarrollo es obligatorio.''' + NCHAR(10) + N'            IF @ERR = '''' AND @DS_TIPO = ''REALIZADO''' + NCHAR(10) + N'            BEGIN' + NCHAR(10) + N'                /* la suma de los desarrollos del consultor en la visita no puede superar sus horas en esa visita */' + NCHAR(10) + N'                SELECT @DS_USADAS = ISNULL(SUM(D.HORAS), 0) FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                WHERE D.ID_VISITA = @DS_VIS AND D.ID_CONSULTOR = @DS_CONS AND D.TIPO = ''REALIZADO'' AND D.ID <> ISNULL(@DS_ID, -1);' + NCHAR(10) + N'                IF @DS_USADAS + @DS_HRS > ISNULL(@DS_VH, 0)' + NCHAR(10) + N'                    SET @ERR = ''La visita del '' + CONVERT(VARCHAR(10), @DS_VDES, 103) + '' tiene '' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), @DS_VH)), ''.0'', '''') + '' h; ya hay '' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), @DS_USADAS)), ''.0'', '''')' + NCHAR(10) + N'                             + '' h cargadas en desarrollos. Disponible: '' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), CASE WHEN ISNULL(@DS_VH, 0) > @DS_USADAS THEN @DS_VH - @DS_USADAS ELSE 0 END)), ''.0'', '''') + '' h.'';' + NCHAR(10) + N'            END;' + NCHAR(10) + N'            IF @DS_TIPO = ''PLANIFICADO'' SET @DS_HRS = NULL;' + NCHAR(10) + N'        END;' + NCHAR(10) + N'' + NCHAR(10) + N'        IF @ERR = '''' AND @B_CMD = ''PV_PL_CERRAR''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' valid(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* grabar */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'IF @B_CMD = ''PV_PL_CERRAR''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'/* ===== PL_DES_V1: grabar ===== */' + NCHAR(10) + N'                IF @B_CMD = ''PV_PL_IMPORTAR''' + NCHAR(10) + N'                BEGIN' + NCHAR(10) + N'                    INSERT INTO dbo.VCT_PROYECTOS_PLANES (ID_PROYECTO, ID_PROYECTO_SERVICIO, ID_DOCUMENTO, VERSION, ESTADO, ID_CONSULTOR_RESPONSABLE, FECHA_INICIO, FECHA_ALTA, USUARIO_ALTA)' + NCHAR(10) + N'                    VALUES (@ID_PROYECTO, @PL_PS, @PL_DOC, 1, ''VIGENTE'', @PL_LIDER, ISNULL(@PL_P_INI, @HOY), GETDATE(), @IAGENTE);' + NCHAR(10) + N'                    SET @PL_PLAN = SCOPE_IDENTITY();' + NCHAR(10) + N'                    /* capitulos, items (hijos del capitulo) y subitems (hijos del item) con las fechas del archivo */' + NCHAR(10) + N'                    INSERT INTO dbo.VCT_PROYECTOS_PLAN_ITEMS (ID_PLAN, CODIGO_ITEM, TITULO, GRUPO, ORDEN, OBLIGATORIO, ESTADO, PORCENTAJE_AVANCE, FECHA_ALTA, USUARIO_ALTA)' + NCHAR(10) + N'                    SELECT @PL_PLAN, X.COD, X.TIT, ''CAPITULO'', X.ORD, 0, ''PENDIENTE'', 0, GETDATE(), @IAGENTE FROM @IX X WHERE X.NIV = 1 ORDER BY X.ORD;' + NCHAR(10) + N'                    UPDATE X SET ID = I.ID FROM @IX X INNER JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I ON I.ID_PLAN = @PL_PLAN AND I.CODIGO_ITEM = X.COD WHERE X.NIV = 1;' + NCHAR(10) + N'                    INSERT INTO dbo.VCT_PROYECTOS_PLAN_ITEMS (ID_PLAN, ID_PADRE, CODIGO_ITEM, TITULO, GRUPO, ORDEN, OBLIGATORIO, ESTADO, FECHA_INICIO, FECHA_VENCIMIENTO, PORCENTAJE_AVANCE, FECHA_ALTA, USUARIO_ALTA)' + NCHAR(10) + N'                    SELECT @PL_PLAN, Y.ID, X.COD, X.TIT, ''PLAN ESTRATEGICO'', X.ORD, 0, ''PENDIENTE'', X.FI, X.FF, 0, GETDATE(), @IAGENTE' + NCHAR(10) + N'                    FROM @IX X LEFT JOIN @IX Y ON Y.COD = X.PAD AND Y.NIV = 1 WHERE X.NIV = 2 ORDER BY X.ORD;' + NCHAR(10) + N'                    UPDATE X SET ID = I.ID FROM @IX X INNER JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I ON I.ID_PLAN = @PL_PLAN AND I.CODIGO_ITEM = X.COD WHERE X.NIV = 2;' + NCHAR(10) + N'                    INSERT INTO dbo.VCT_PROYECTOS_PLAN_ITEMS (ID_PLAN, ID_PADRE, CODIGO_ITEM, TITULO, GRUPO, ORDEN, OBLIGATORIO, ESTADO, FECHA_INICIO, FECHA_VENCIMIENTO, PORCENTAJE_AVANCE, FECHA_ALTA, USUARIO_ALTA)' + NCHAR(10) + N'                    SELECT @PL_PLAN, Y.ID, X.COD, X.TIT, ''PLAN ESTRATEGICO'', X.ORD, 0, ''PENDIENTE'', X.FI, X.FF, 0, GETDATE(), @IAGENTE' + NCHAR(10) + N'                    FROM @IX X INNER JOIN @IX Y ON Y.COD = X.PAD AND Y.NIV = 2 WHERE X.NIV = 3 ORDER BY X.ORD;' + NCHAR(10) + N'                    /* la accion "Carga del plan" pasa a En proceso y queda ligada al plan */' + NCHAR(10) + N'                    SELECT TOP 1 @PL_ACC = A.ID, @PL_ACC_EST = A.ID_ESTADO FROM dbo.VCT_ACCIONES A' + NCHAR(10) + N'                    INNER JOIN dbo.VCT_PRM_ACCIONES_SUBTIPOS ST ON ST.ID = A.ID_SUBTIPO AND ST.CODIGO = ''CARGA_PLAN''' + NCHAR(10) + N'                    WHERE A.ID_PROYECTO = @ID_PROYECTO AND A.ID_ESTADO = @PL_PEND ORDER BY A.ID;' + NCHAR(10) + N'                    IF @PL_ACC IS NOT NULL AND @PL_PROC IS NOT NULL' + NCHAR(10) + N'                    BEGIN' + NCHAR(10) + N'                        UPDATE dbo.VCT_ACCIONES SET ID_ESTADO = @PL_PROC, ID_PLAN = @PL_PLAN, FECHA_UPD = GETDATE(), USUARIO_UPD = @IAGENTE WHERE ID = @PL_ACC;' + NCHAR(10) + N'                        INSERT INTO dbo.VCT_ACCIONES_HISTORIAL (ID_ACCION, ID_ESTADO_ANTERIOR, ID_ESTADO_NUEVO, ACCION, DESCRIPCION, TIPO_ACTOR, FECHA, USUARIO)' + NCHAR(10) + N'                        VALUES (@PL_ACC, @PL_ACC_EST, @PL_PROC, ''PLAN_GENERADO'', ''Se carg'' + CHAR(243) + '' el plan del proyecto desde Excel.'', ''USUARIO'', GETDATE(), @IAGENTE);' + NCHAR(10) + N'                    END;' + NCHAR(10) + N'                    SET @MSG = ''Plan cargado desde Excel: '' + CONVERT(VARCHAR(10), (SELECT COUNT(*) FROM @IX WHERE NIV = 1)) + '' cap'' + CHAR(237) + ''tulo(s), ''' + NCHAR(10) + N'                             + CONVERT(VARCHAR(10), (SELECT COUNT(*) FROM @IX WHERE NIV = 2)) + '' '' + CHAR(237) + ''tem(s) y ''' + NCHAR(10) + N'                             + CONVERT(VARCHAR(10), (SELECT COUNT(*) FROM @IX WHERE NIV = 3)) + '' sub'' + CHAR(237) + ''tem(s).'';' + NCHAR(10) + N'                END;' + NCHAR(10) + N'' + NCHAR(10) + N'                IF @B_CMD = ''PV_PL_BORRAR''' + NCHAR(10) + N'                BEGIN' + NCHAR(10) + N'                    /* acciones del plan (y sus hijas); la accion "Carga del plan" no se borra: vuelve a Pendiente */' + NCHAR(10) + N'                    CREATE TABLE #PLX (ID INT PRIMARY KEY);' + NCHAR(10) + N'                    INSERT INTO #PLX (ID)' + NCHAR(10) + N'                    SELECT A.ID FROM dbo.VCT_ACCIONES A' + NCHAR(10) + N'                    WHERE A.ID_PROYECTO = @ID_PROYECTO AND A.ID <> @PL_ACC' + NCHAR(10) + N'                      AND (A.ID_PLAN = @PL_PLAN OR A.ID_PLAN_ITEM IN (SELECT I.ID FROM dbo.VCT_PROYECTOS_PLAN_ITEMS I WHERE I.ID_PLAN = @PL_PLAN));' + NCHAR(10) + N'                    WHILE 1 = 1' + NCHAR(10) + N'                    BEGIN' + NCHAR(10) + N'                        INSERT INTO #PLX (ID)' + NCHAR(10) + N'                        SELECT A.ID FROM dbo.VCT_ACCIONES A WHERE A.ID_ACCION_PADRE IN (SELECT ID FROM #PLX) AND A.ID NOT IN (SELECT ID FROM #PLX) AND A.ID <> @PL_ACC;' + NCHAR(10) + N'                        IF @@ROWCOUNT = 0 BREAK;' + NCHAR(10) + N'                    END;' + NCHAR(10) + N'                    UPDATE dbo.VCT_ACCIONES SET ID_ACCION_PADRE = NULL WHERE ID_ACCION_PADRE IN (SELECT ID FROM #PLX) AND ID NOT IN (SELECT ID FROM #PLX);' + NCHAR(10) + N'                    /* tablas que cuelgan de las acciones: las VCT_ACCIONES_* se borran; otras con referencia que admite nulo, se limpia */' + NCHAR(10) + N'                    DECLARE @PX_SQL NVARCHAR(MAX), @PX_T NVARCHAR(300), @PX_N SYSNAME, @PX_C NVARCHAR(200), @PX_NUL BIT;' + NCHAR(10) + N'                    DECLARE px CURSOR LOCAL FAST_FORWARD FOR' + NCHAR(10) + N'                        SELECT QUOTENAME(OBJECT_SCHEMA_NAME(fk.parent_object_id)) + N''.'' + QUOTENAME(OBJECT_NAME(fk.parent_object_id)), OBJECT_NAME(fk.parent_object_id), QUOTENAME(c.name), c.is_nullable' + NCHAR(10) + N'                        FROM sys.foreign_keys fk' + NCHAR(10) + N'                        INNER JOIN sys.foreign_key_columns k ON k.constraint_object_id = fk.object_id' + NCHAR(10) + N'                        INNER JOIN sys.columns c ON c.object_id = k.parent_object_id AND c.column_id = k.parent_column_id' + NCHAR(10) + N'                        WHERE fk.referenced_object_id = OBJECT_ID(''dbo.VCT_ACCIONES'') AND fk.parent_object_id <> fk.referenced_object_id' + NCHAR(10) + N'                          AND (SELECT COUNT(*) FROM sys.foreign_key_columns k2 WHERE k2.constraint_object_id = fk.object_id) = 1;' + NCHAR(10) + N'                    OPEN px;' + NCHAR(10) + N'                    FETCH NEXT FROM px INTO @PX_T, @PX_N, @PX_C, @PX_NUL;' + NCHAR(10) + N'                    WHILE @@FETCH_STATUS = 0' + NCHAR(10) + N'                    BEGIN' + NCHAR(10) + N'                        IF @PX_N LIKE ''VCT[_]ACCIONES[_]%''' + NCHAR(10) + N'                            SET @PX_SQL = N''DELETE FROM '' + @PX_T + N'' WHERE '' + @PX_C + N'' IN (SELECT ID FROM #PLX);''' + NCHAR(10) + N'                        ELSE IF @PX_NUL = 1' + NCHAR(10) + N'                            SET @PX_SQL = N''UPDATE '' + @PX_T + N'' SET '' + @PX_C + N'' = NULL WHERE '' + @PX_C + N'' IN (SELECT ID FROM #PLX);''' + NCHAR(10) + N'                        ELSE' + NCHAR(10) + N'                            SET @PX_SQL = N''IF EXISTS (SELECT 1 FROM '' + @PX_T + N'' WHERE '' + @PX_C + N'' IN (SELECT ID FROM #PLX)) RAISERROR(''''La tabla '' + REPLACE(@PX_N, '''''''', '''') + N'' depende de las acciones del plan.'''', 16, 1);'';' + NCHAR(10) + N'                        EXEC sys.sp_executesql @PX_SQL;' + NCHAR(10) + N'                        FETCH NEXT FROM px INTO @PX_T, @PX_N, @PX_C, @PX_NUL;' + NCHAR(10) + N'                    END;' + NCHAR(10) + N'                    CLOSE px;' + NCHAR(10) + N'                    DEALLOCATE px;' + NCHAR(10) + N'                    DELETE FROM dbo.VCT_ACCIONES WHERE ID IN (SELECT ID FROM #PLX);' + NCHAR(10) + N'                    UPDATE dbo.VCT_ACCIONES SET ID_ESTADO = @PL_PEND, ID_RESULTADO = NULL, ID_PLAN = NULL, ID_PLAN_ITEM = NULL, FECHA_CIERRE = NULL, FECHA_UPD = GETDATE(), USUARIO_UPD = @IAGENTE' + NCHAR(10) + N'                    WHERE ID = @PL_ACC;' + NCHAR(10) + N'                    INSERT INTO dbo.VCT_ACCIONES_HISTORIAL (ID_ACCION, ID_ESTADO_ANTERIOR, ID_ESTADO_NUEVO, ACCION, DESCRIPCION, TIPO_ACTOR, FECHA, USUARIO)' + NCHAR(10) + N'                    VALUES (@PL_ACC, @PL_ACC_EST, @PL_PEND, ''PLAN_ELIMINADO'', ''Se elimin'' + CHAR(243) + '' el plan para volver a cargarlo.'', ''USUARIO'', GETDATE(), @IAGENTE);' + NCHAR(10) + N'                    DELETE FROM dbo.VCT_PROYECTOS_PLAN_ITEMS WHERE ID_PLAN = @PL_PLAN;' + NCHAR(10) + N'                    DELETE FROM dbo.VCT_PROYECTOS_PLANES WHERE ID = @PL_PLAN;' + NCHAR(10) + N'                    SET @MSG = ''Plan eliminado: se puede volver a cargar con el plan base, un Excel o en blanco.'';' + NCHAR(10) + N'                END;' + NCHAR(10) + N'' + NCHAR(10) + N'                IF @B_CMD = ''PV_PL_DES_GUARDAR''' + NCHAR(10) + N'                BEGIN' + NCHAR(10) + N'                    IF @DS_ID IS NULL' + NCHAR(10) + N'                    BEGIN' + NCHAR(10) + N'                        INSERT INTO dbo.VCT_ACCIONES_DESARROLLO (ID_ACCION, ID_VISITA, ID_CONSULTOR, TIPO, HORAS, TITULO, DESARROLLO, PROXIMO_PASO, FECHA_ALTA, USUARIO_ALTA)' + NCHAR(10) + N'                        VALUES (@DS_ACC, @DS_VIS, @DS_CONS, @DS_TIPO, @DS_HRS, LEFT(@PL_T15, 300), NULLIF(@PL_T16, ''''), NULLIF(LEFT(@PL_T17, 1000), ''''), GETDATE(), @IAGENTE);' + NCHAR(10) + N'                        SET @MSG = ''Desarrollo agregado.'';' + NCHAR(10) + N'                    END' + NCHAR(10) + N'                    ELSE' + NCHAR(10) + N'                    BEGIN' + NCHAR(10) + N'                        UPDATE dbo.VCT_ACCIONES_DESARROLLO' + NCHAR(10) + N'                           SET ID_ACCION = @DS_ACC, ID_VISITA = @DS_VIS, ID_CONSULTOR = @DS_CONS, TIPO = @DS_TIPO, HORAS = @DS_HRS, TITULO = LEFT(@PL_T15, 300),' + NCHAR(10) + N'                               DESARROLLO = NULLIF(@PL_T16, ''''), PROXIMO_PASO = NULLIF(LEFT(@PL_T17, 1000), ''''), FECHA_UPD = GETDATE(), USUARIO_UPD = @IAGENTE' + NCHAR(10) + N'                         WHERE ID = @DS_ID;' + NCHAR(10) + N'                        SET @MSG = ''Desarrollo actualizado.'';' + NCHAR(10) + N'                    END;' + NCHAR(10) + N'                    INSERT INTO dbo.VCT_ACCIONES_HISTORIAL (ID_ACCION, ID_ESTADO_ANTERIOR, ID_ESTADO_NUEVO, ACCION, DESCRIPCION, TIPO_ACTOR, FECHA, USUARIO)' + NCHAR(10) + N'                    VALUES (@DS_ACC, @DS_EST, @DS_EST, ''DESARROLLO'',' + NCHAR(10) + N'                            LEFT(CASE WHEN @DS_TIPO = ''REALIZADO'' THEN ''Desarrollo realizado (visita del '' + CONVERT(VARCHAR(10), @DS_VDES, 103) + '', '' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), @DS_HRS)), ''.0'', '''') + '' h): ''' + NCHAR(10) + N'                                      ELSE ''Desarrollo planificado (visita del '' + CONVERT(VARCHAR(10), @DS_VDES, 103) + ''): '' END + @PL_T15, 2000), ''USUARIO'', GETDATE(), @IAGENTE);' + NCHAR(10) + N'                END;' + NCHAR(10) + N'                IF @B_CMD = ''PV_PL_DES_BORRAR''' + NCHAR(10) + N'                BEGIN' + NCHAR(10) + N'                    DELETE FROM dbo.VCT_ACCIONES_DESARROLLO WHERE ID = @DS_ID;' + NCHAR(10) + N'                    INSERT INTO dbo.VCT_ACCIONES_HISTORIAL (ID_ACCION, ID_ESTADO_ANTERIOR, ID_ESTADO_NUEVO, ACCION, DESCRIPCION, TIPO_ACTOR, FECHA, USUARIO)' + NCHAR(10) + N'                    SELECT A.ID, A.ID_ESTADO, A.ID_ESTADO, ''DESARROLLO_ELIMINADO'', ''Se elimin'' + CHAR(243) + '' un registro de desarrollo.'', ''USUARIO'', GETDATE(), @IAGENTE' + NCHAR(10) + N'                    FROM dbo.VCT_ACCIONES A WHERE A.ID = @DS_OLD_ACC;' + NCHAR(10) + N'                    SET @MSG = ''Desarrollo eliminado.'';' + NCHAR(10) + N'                END;' + NCHAR(10) + N'' + NCHAR(10) + N'                IF @B_CMD = ''PV_PL_CERRAR''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' grabar(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* ag_borrar */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'ELSE IF @AG_ID IS NOT NULL AND EXISTS (SELECT 1 FROM dbo.VCT_PROYECTOS_VISITAS_REGISTRO WITH(NOLOCK) WHERE ID_VISITA = @AG_ID)';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'ELSE IF @B_CMD = ''PV_AG_BORRAR'' AND @AG_ID IS NOT NULL AND OBJECT_ID(''dbo.VCT_ACCIONES_DESARROLLO'', ''U'') IS NOT NULL' + NCHAR(10) + N'             AND EXISTS (SELECT 1 FROM dbo.VCT_ACCIONES_DESARROLLO WITH(NOLOCK) WHERE ID_VISITA = @AG_ID)' + NCHAR(10) + N'            SET @ERR = ''La visita tiene desarrollo de acciones del plan cargado: no se puede eliminar.''   /* PL_DES_V1 */' + NCHAR(10) + N'        ELSE IF @AG_ID IS NOT NULL AND EXISTS (SELECT 1 FROM dbo.VCT_PROYECTOS_VISITAS_REGISTRO WITH(NOLOCK) WHERE ID_VISITA = @AG_ID)';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' ag_borrar(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* pi_cols */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'HTML VARCHAR(MAX), DHTML VARCHAR(MAX));';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'HTML VARCHAR(MAX), DHTML VARCHAR(MAX), HS NUMERIC(18,2), ND INT, NP INT);';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' pi_cols(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* pa_cols */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'EST_DES VARCHAR(100), EST_COD VARCHAR(30), CIERRE DATETIME, HTML VARCHAR(MAX));';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'EST_DES VARCHAR(100), EST_COD VARCHAR(30), CIERRE DATETIME, HTML VARCHAR(MAX),' + NCHAR(10) + N'                      HS NUMERIC(18,2), ND INT, NP INT, FI_IT DATETIME, FF_IT DATETIME, RHTML VARCHAR(MAX));';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' pa_cols(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* d1 */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'FROM #PA A INNER JOIN #PI P ON P.ID = A.ITEM;';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'FROM #PA A INNER JOIN #PI P ON P.ID = A.ITEM;' + NCHAR(10) + N'        /* PL_DES_V1: desarrollo de las acciones: horas realizadas y planificados por accion, item / subitem y capitulo */' + NCHAR(10) + N'        IF OBJECT_ID(''dbo.VCT_ACCIONES_DESARROLLO'', ''U'') IS NOT NULL' + NCHAR(10) + N'            UPDATE A SET HS = ISNULL(X.HS, 0), ND = ISNULL(X.ND, 0), NP = ISNULL(X.NP, 0)' + NCHAR(10) + N'            FROM #PA A' + NCHAR(10) + N'            OUTER APPLY (SELECT SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN ISNULL(D.HORAS, 0) ELSE 0 END) AS HS,' + NCHAR(10) + N'                                SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN 1 ELSE 0 END) AS ND,' + NCHAR(10) + N'                                SUM(CASE WHEN D.TIPO = ''PLANIFICADO'' THEN 1 ELSE 0 END) AS NP' + NCHAR(10) + N'                         FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_ACCION = A.ID) X;' + NCHAR(10) + N'        UPDATE P SET HS = ISNULL((SELECT SUM(A.HS) FROM #PA A WHERE A.ITEM = P.ID OR A.ITEM IN (SELECT S.ID FROM #PI S WHERE S.PADRE = P.ID AND S.NIV = 3)), 0),' + NCHAR(10) + N'                     ND = ISNULL((SELECT SUM(A.ND) FROM #PA A WHERE A.ITEM = P.ID OR A.ITEM IN (SELECT S.ID FROM #PI S WHERE S.PADRE = P.ID AND S.NIV = 3)), 0),' + NCHAR(10) + N'                     NP = ISNULL((SELECT SUM(A.NP) FROM #PA A WHERE A.ITEM = P.ID OR A.ITEM IN (SELECT S.ID FROM #PI S WHERE S.PADRE = P.ID AND S.NIV = 3)), 0)' + NCHAR(10) + N'        FROM #PI P WHERE P.NIV > 1;' + NCHAR(10) + N'        UPDATE C SET HS = ISNULL((SELECT SUM(X.HS) FROM #PI X WHERE X.NIV = 2 AND X.CHAP = C.ID), 0),' + NCHAR(10) + N'                     ND = ISNULL((SELECT SUM(X.ND) FROM #PI X WHERE X.NIV = 2 AND X.CHAP = C.ID), 0),' + NCHAR(10) + N'                     NP = ISNULL((SELECT SUM(X.NP) FROM #PI X WHERE X.NIV = 2 AND X.CHAP = C.ID), 0)' + NCHAR(10) + N'        FROM #PI C WHERE C.NIV = 1;' + NCHAR(10) + N'        /* rango de cada accion: fechas propias del item / subitem o, si no tiene, las del item superior */' + NCHAR(10) + N'        UPDATE A SET FI_IT = ISNULL(P.FI, T.FI), FF_IT = ISNULL(P.FF, T.FF)' + NCHAR(10) + N'        FROM #PA A INNER JOIN #PI P ON P.ID = A.ITEM LEFT JOIN #PI T ON T.ID = P.TOPI;';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' d1(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* num */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'/* ---------- numeros ---------- */';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'/* PL_DES_V1: primera visita del proyecto (desde ahi corre el tiempo transcurrido) y desarrollo cargado */' + NCHAR(10) + N'    DECLARE @F_V1 DATETIME, @PL_DES_N INT = 0, @PL_DHS NUMERIC(18,2) = 0;' + NCHAR(10) + N'    SELECT @F_V1 = MIN(CONVERT(DATETIME, CONVERT(DATE, V.FECHA_DESDE))) FROM dbo.VCT_PROYECTOS_VISITAS V WITH(NOLOCK)' + NCHAR(10) + N'    WHERE V.ID_PROYECTO = @ID_PROYECTO AND UPPER(LTRIM(RTRIM(ISNULL(V.ESTADO,'''')))) NOT IN (''CANCELADO'',''ANULADO'');' + NCHAR(10) + N'    IF OBJECT_ID(''dbo.VCT_ACCIONES_DESARROLLO'', ''U'') IS NOT NULL' + NCHAR(10) + N'        SELECT @PL_DES_N = COUNT(*), @PL_DHS = ISNULL(SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN ISNULL(D.HORAS, 0) ELSE 0 END), 0)' + NCHAR(10) + N'        FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) INNER JOIN dbo.VCT_ACCIONES A WITH(NOLOCK) ON A.ID = D.ID_ACCION' + NCHAR(10) + N'        WHERE A.ID_PROYECTO = @ID_PROYECTO;' + NCHAR(10) + N'' + NCHAR(10) + N'    /* ---------- numeros ---------- */';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' num(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* pct1 */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'IF @F_INI IS NOT NULL AND @F_FIN IS NOT NULL AND @F_FIN > @F_INI';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'IF @F_V1 IS NOT NULL AND @F_FIN IS NOT NULL AND @F_FIN > @F_V1';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' pct1(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* pct2 */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'SET @PCT_T = CASE WHEN @HOY <= @F_INI THEN 0 WHEN @HOY >= @F_FIN THEN 100';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'SET @PCT_T = CASE WHEN @HOY <= @F_V1 THEN 0 WHEN @HOY >= @F_FIN THEN 100';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' pct2(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* pct3 */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'ELSE CONVERT(INT, ROUND(DATEDIFF(DAY, @F_INI, @HOY) * 100.0 / DATEDIFF(DAY, @F_INI, @F_FIN), 0)) END;';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'ELSE CONVERT(INT, ROUND(DATEDIFF(DAY, @F_V1, @HOY) * 100.0 / DATEDIFF(DAY, @F_V1, @F_FIN), 0)) END;';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' pct3(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* rango */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'@PL_RANGO INT = CASE WHEN @F_INI IS NOT NULL AND @F_FIN IS NOT NULL AND @F_FIN > @F_INI THEN DATEDIFF(DAY, @F_INI, @F_FIN) ELSE 0 END,';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'@PL_RANGO INT = CASE WHEN @F_V1 IS NOT NULL AND @F_FIN IS NOT NULL AND @F_FIN > @F_V1 THEN DATEDIFF(DAY, @F_V1, @F_FIN) ELSE 0 END,';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' rango(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* hoyp */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'IF @PL_RANGO > 0 SET @PL_HOYP = CASE WHEN @HOY <= @F_INI THEN 0 WHEN @HOY >= @F_FIN THEN 100 ELSE DATEDIFF(DAY, @F_INI, @HOY) * 100 / @PL_RANGO END;';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'IF @PL_RANGO > 0 SET @PL_HOYP = CASE WHEN @HOY <= @F_V1 THEN 0 WHEN @HOY >= @F_FIN THEN 100 ELSE DATEDIFF(DAY, @F_V1, @HOY) * 100 / @PL_RANGO END;';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' hoyp(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* tv_lbl */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'''<div class="vct-pl-tv"><div><span>Tiempo transcurrido del proyecto</span>';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'''<div class="vct-pl-tv"><div><span>Tiempo transcurrido '' + CASE WHEN @F_V1 IS NULL THEN ''(sin visitas cargadas)'' ELSE ''desde la 1&ordf; visita ('' + CONVERT(VARCHAR(10), @F_V1, 103) + '')'' END + ''</span>';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' tv_lbl(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* rs_lbl */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'''<div><span>Tiempo transcurrido</span><b>''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'''<div><span>Tiempo transcurrido'' + CASE WHEN @F_V1 IS NULL THEN '' (sin visitas)'' ELSE '' desde la 1&ordf; visita'' END + ''</span><b>''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' rs_lbl(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* tv_dev */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'+   ''<p class="vct-pl-tv-note">''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'+   ''<div><span>Horas de visita volcadas en desarrollos (informativo)</span><div class="vct-pl-tv-bar"><span class="is-dev" style="width:'' + CONVERT(VARCHAR(10), CASE WHEN @H_EJEC > 0 THEN CASE WHEN @PL_DHS >= @H_EJEC THEN 100 ELSE CONVERT(INT, ROUND(@PL_DHS * 100.0 / @H_EJEC, 0)) END ELSE 0 END) + ''%"></span></div><b>'' + CONVERT(VARCHAR(10), CASE WHEN @H_EJEC > 0 THEN CASE WHEN @PL_DHS >= @H_EJEC THEN 100 ELSE CONVERT(INT, ROUND(@PL_DHS * 100.0 / @H_EJEC, 0)) END ELSE 0 END) + ''%</b></div>''' + NCHAR(10) + N'            +   ''<p class="vct-pl-tv-note">''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' tv_dev(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* tv_note */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'+ '' acciones cumplidas</p></div></div>''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'+ '' acciones cumplidas'' + CASE WHEN @PL_DHS > 0 THEN '' &middot; '' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), @PL_DHS)), ''.0'', '''') + '' h en desarrollos de '' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), @H_EJEC)), ''.0'', '''') + '' h ejecutadas'' ELSE '''' END + ''</p></div></div>''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' tv_note(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* hdr */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'<span class="vct-plt-c">Acciones</span><span>Estado</span><span></span></div>''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'<span class="vct-plt-c">Acciones</span><span class="vct-plt-c vct-plt-hs" title="Horas cargadas en desarrollos realizados (+ planificados)">Horas dev.</span><span>Estado</span><span></span></div>''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' hdr(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* ch_cnt */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'+ ''<span class="vct-plt-c vct-plt-cnt">'' + CONVERT(VARCHAR(10), C.CUMP) + ''/'' + CONVERT(VARCHAR(10), C.TOT) + '' acc.</span><span class="vct-plt-b"></span><span class="vct-plt-m"></span></div>''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'+ ''<span class="vct-plt-c vct-plt-cnt">'' + CONVERT(VARCHAR(10), C.CUMP) + ''/'' + CONVERT(VARCHAR(10), C.TOT) + '' acc.</span>'' + ''<span class="vct-plt-c vct-plt-hs'' + CASE WHEN ISNULL(C.HS, 0) = 0 AND ISNULL(C.NP, 0) = 0 THEN '' is-none">-'' ELSE ''" title="'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(C.HS, 0))), ''.0'', '''') + '' h en desarrollos realizados'' + CASE WHEN ISNULL(C.NP, 0) > 0 THEN '' &middot; '' + CONVERT(VARCHAR(10), C.NP) + '' planificado(s)'' ELSE '''' END + ''"><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(C.HS, 0))), ''.0'', '''') + '' h</b>'' + CASE WHEN ISNULL(C.NP, 0) > 0 THEN ''<i>+'' + CONVERT(VARCHAR(10), C.NP) + ''</i>'' ELSE '''' END END + ''</span>'' + ''<span class="vct-plt-b"></span><span class="vct-plt-m"></span></div>''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' ch_cnt(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* ch_small */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'+ @PL_SEP + CONVERT(VARCHAR(10), C.CUMP) + '' de '' + CONVERT(VARCHAR(10), C.TOT) + '' acciones cumplidas''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'+ @PL_SEP + CONVERT(VARCHAR(10), C.CUMP) + '' de '' + CONVERT(VARCHAR(10), C.TOT) + '' acciones cumplidas'' + CASE WHEN ISNULL(C.HS, 0) > 0 THEN @PL_SEP + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), C.HS)), ''.0'', '''') + '' h en desarrollos'' ELSE '''' END';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' ch_small(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* ch_x */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'X.AV, X.TOT, X.CUMP, X.VEN, X.FI, X.FF,';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'X.AV, X.TOT, X.CUMP, X.VEN, X.FI, X.FF, ISNULL(X.HS, 0) AS HS, ISNULL(X.NP, 0) AS NP,';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' ch_x(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* ch_z */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'SUM(TOT), SUM(CUMP), SUM(VEN), MIN(FI), MAX(FF), COUNT(*),';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'SUM(TOT), SUM(CUMP), SUM(VEN), MIN(FI), MAX(FF), ISNULL(SUM(HS), 0), ISNULL(SUM(NP), 0), COUNT(*),';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' ch_z(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* it_cnt */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'+ ''<span class="vct-plt-c vct-plt-cnt">'' + CONVERT(VARCHAR(10), T.CUMP) + ''/'' + CONVERT(VARCHAR(10), T.TOT) + '' acc.'' + CASE WHEN T.VEN > 0 THEN '' &middot; <b>'' + CONVERT(VARCHAR(10), T.VEN) + '' venc.</b>'' ELSE '''' END + ''</span>''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'+ ''<span class="vct-plt-c vct-plt-cnt">'' + CONVERT(VARCHAR(10), T.CUMP) + ''/'' + CONVERT(VARCHAR(10), T.TOT) + '' acc.'' + CASE WHEN T.VEN > 0 THEN '' &middot; <b>'' + CONVERT(VARCHAR(10), T.VEN) + '' venc.</b>'' ELSE '''' END + ''</span>''' + NCHAR(10) + N'            + ''<span class="vct-plt-c vct-plt-hs'' + CASE WHEN ISNULL(T.HS, 0) = 0 AND ISNULL(T.NP, 0) = 0 THEN '' is-none">-'' ELSE ''" title="'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(T.HS, 0))), ''.0'', '''') + '' h en desarrollos realizados'' + CASE WHEN ISNULL(T.NP, 0) > 0 THEN '' &middot; '' + CONVERT(VARCHAR(10), T.NP) + '' planificado(s)'' ELSE '''' END + ''"><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(T.HS, 0))), ''.0'', '''') + '' h</b>'' + CASE WHEN ISNULL(T.NP, 0) > 0 THEN ''<i>+'' + CONVERT(VARCHAR(10), T.NP) + ''</i>'' ELSE '''' END END + ''</span>''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' it_cnt(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* meta */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'''<div class="vct-plt-meta-pg"><small>Avance</small>';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'''<div><small>Horas desarrollo</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(T.HS, 0))), ''.0'', '''') + '' h'' + CASE WHEN ISNULL(T.NP, 0) > 0 THEN '' &middot; '' + CONVERT(VARCHAR(10), T.NP) + '' planif.'' ELSE '''' END + ''</b></div>''' + NCHAR(10) + N'            + ''<div class="vct-plt-meta-pg"><small>Avance</small>';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' meta(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* new_pa */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'data-vct-pv-new="pa" data-id="'' + CONVERT(VARCHAR(20), T.ID) + ''"';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'data-vct-pv-new="pa" data-id="'' + CONVERT(VARCHAR(20), T.ID) + ''" data-rng="'' + ISNULL(CONVERT(VARCHAR(10), ISNULL(T.FI, (SELECT X.FI FROM #PI X WHERE X.ID = T.TOPI)), 120), '''') + ''|'' + ISNULL(CONVERT(VARCHAR(10), ISNULL(T.FF, (SELECT X.FF FROM #PI X WHERE X.ID = T.TOPI)), 120), '''') + ''"';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 2 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' new_pa(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* edit_pa */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'data-vct-pv-edit="pa" data-id="'' + CONVERT(VARCHAR(20), A.ITEM) + ''" data-f-accid="'' + CONVERT(VARCHAR(20), A.ID) + ''"''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'data-vct-pv-edit="pa" data-id="'' + CONVERT(VARCHAR(20), A.ITEM) + ''" data-f-accid="'' + CONVERT(VARCHAR(20), A.ID) + ''"'' + '' data-rng="'' + ISNULL(CONVERT(VARCHAR(10), A.FI_IT, 120), '''') + ''|'' + ISNULL(CONVERT(VARCHAR(10), A.FF_IT, 120), '''') + ''"''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' edit_pa(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* ck1 */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'+ CASE WHEN @PUEDE_PLAN = 1 AND A.CUMPLIDA = 1';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'+ ''<span class="vct-pl-dtg" data-pl-dtg role="button" tabindex="0" title="Ver desarrollo"><span data-vct-icon="chevron-right"></span></span>''   /* PL_DES_V1: sin tilde de cumplida */' + NCHAR(10) + N'            + CASE WHEN 1 = 0';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' ck1(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* ck2 */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'WHEN @PUEDE_PLAN = 1 AND A.FINAL = 0';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'WHEN 1 = 0';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' ck2(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* ck3 */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'ELSE ''<span class="vct-pl-ck'' + CASE WHEN A.CUMPLIDA = 1 THEN '' is-on'' ELSE '''' END + ''">'' + CASE WHEN A.CUMPLIDA = 1 THEN ''<span data-vct-icon="check"></span>'' ELSE '''' END + ''</span>'' END';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'ELSE '''' END';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' ck3(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* chip */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'+ ''<span class="vct-plt-resp is-ini">'' + CASE WHEN A.RESP_INI <> ''''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'+ ''<span class="vct-pl-dchip'' + CASE WHEN ISNULL(A.ND, 0) + ISNULL(A.NP, 0) = 0 THEN '' is-none">Sin desarrollo'' ELSE ''" title="Desarrollo de la acci&oacute;n">'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(A.HS, 0))), ''.0'', '''') + '' h &middot; '' + CONVERT(VARCHAR(10), ISNULL(A.ND, 0)) + '' reg.'' + CASE WHEN ISNULL(A.NP, 0) > 0 THEN '' &middot; '' + CONVERT(VARCHAR(10), A.NP) + '' planif.'' ELSE '''' END END + ''</span>''' + NCHAR(10) + N'            + ''<span class="vct-plt-resp is-ini">'' + CASE WHEN A.RESP_INI <> ''''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' chip(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* menu */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'+ CASE WHEN @PUEDE_PLAN = 1 THEN ''<span class="vct-pl-menu">'' + @PL_TRIG + ''<div class="vctdg-rowmenu-items" hidden>''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'+ CASE WHEN @PUEDE_PLAN = 1 THEN ''<span class="vct-pl-menu">'' + @PL_TRIG + ''<div class="vctdg-rowmenu-items" hidden>''' + NCHAR(10) + N'                + ''<button type="button" class="vct-pv-menu-btn" data-pl-des-new="'' + CONVERT(VARCHAR(20), A.ID) + ''"><span data-vct-icon="plus"></span><span>Cargar desarrollo</span></button>''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' menu(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* aw */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'FROM #PA A;';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'FROM #PA A;' + NCHAR(10) + N'        /* PL_DES_V1: accion + su desarrollo (desplegable) */' + NCHAR(10) + N'        UPDATE #PA SET HTML = ''<div class="vct-pl-aw" data-pl-aw="'' + CONVERT(VARCHAR(20), ID) + ''">'' + HTML + ISNULL(RHTML, '''') + ''</div>'';';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' aw(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* rhtml */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'/* fila de accion (detalle): check de cumplida, responsable, vence, estado y menu Editar / Eliminar */';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'/* PL_DES_V1: desarrollo de cada accion (registros realizados / planificados con su visita) */' + NCHAR(10) + N'        IF OBJECT_ID(''dbo.VCT_ACCIONES_DESARROLLO'', ''U'') IS NOT NULL' + NCHAR(10) + N'        UPDATE A SET RHTML = CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pl-regs" data-pl-regs hidden>''' + NCHAR(10) + N'            + ISNULL(NULLIF((' + NCHAR(10) + N'                SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pl-reg">''' + NCHAR(10) + N'                     + ''<span class="vct-pl-reg-d"><b>'' + CONVERT(VARCHAR(5), V.FECHA_DESDE, 103) + ''</b><small>'' + REPLACE(REPLACE(REPLACE(CASE WHEN ISNULL(S.NOMBRE,'''') <> '''' THEN S.NOMBRE ELSE ISNULL(S.DES,'''') END,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; '' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(VH.H, 0))), ''.0'', '''') + '' h</small></span>''' + NCHAR(10) + N'                     + ''<span class="vct-pl-tp '' + CASE WHEN D.TIPO = ''REALIZADO'' THEN ''is-re">Realizado'' ELSE ''is-pl">Planificado'' END + ''</span>''' + NCHAR(10) + N'                     + ''<span class="vct-pl-reg-t"><b>'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                     + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<small>'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 400),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</small>'' ELSE '''' END' + NCHAR(10) + N'                     + CASE WHEN ISNULL(D.PROXIMO_PASO, '''') <> '''' THEN ''<em>Pr&oacute;ximo: '' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</em>'' ELSE '''' END + ''</span>''' + NCHAR(10) + N'                     + ''<span class="vctdg-avatar is-c" title="'' + REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">'' + ISNULL(Y.INI, '''') + ''</span>''' + NCHAR(10) + N'                     + ''<span class="vct-pl-reg-h">'' + CASE WHEN D.TIPO = ''REALIZADO'' THEN REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(D.HORAS, 0))), ''.0'', '''') + '' h'' ELSE ''&ndash;'' END + ''</span>''' + NCHAR(10) + N'                     + CASE WHEN @PUEDE_PLAN = 1 THEN ''<span class="vct-pl-menu">'' + @PL_TRIG + ''<div class="vctdg-rowmenu-items" hidden>''' + NCHAR(10) + N'                          + ''<button type="button" class="vct-pv-menu-btn" data-pl-des-edit="'' + CONVERT(VARCHAR(20), D.ID) + ''" data-acc="'' + CONVERT(VARCHAR(20), D.ID_ACCION) + ''"''' + NCHAR(10) + N'                          + '' data-f-tipo="'' + CASE WHEN D.TIPO = ''REALIZADO'' THEN ''R'' ELSE ''P'' END + ''" data-f-vc="'' + CONVERT(VARCHAR(20), D.ID_VISITA) + '':'' + CONVERT(VARCHAR(20), D.ID_CONSULTOR) + ''"''' + NCHAR(10) + N'                          + '' data-f-hrs="'' + CASE WHEN D.HORAS IS NULL THEN '''' ELSE REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), D.HORAS)), ''.0'', '''') END + ''" data-f-tit="'' + REPLACE(REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''"''' + NCHAR(10) + N'                          + '' data-f-des="'' + REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(D.DESARROLLO, ''''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''" data-f-prox="'' + REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(D.PROXIMO_PASO, ''''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">''' + NCHAR(10) + N'                          + ''<span data-vct-icon="edit"></span><span>Editar</span></button>''' + NCHAR(10) + N'                          + ''<button type="button" class="vct-pv-menu-btn" data-vct-pv-confirm="PV_PL_DES_BORRAR" data-id="'' + CONVERT(VARCHAR(20), D.ID) + ''" data-nombre="'' + REPLACE(REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">''' + NCHAR(10) + N'                          + ''<span data-vct-icon="trash"></span><span>Eliminar</span></button></div></span>'' ELSE ''<span></span>'' END' + NCHAR(10) + N'                     + ''</div>''' + NCHAR(10) + N'                FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                INNER JOIN dbo.VCT_PROYECTOS_VISITAS V WITH(NOLOCK) ON V.ID = D.ID_VISITA' + NCHAR(10) + N'                LEFT JOIN #SV S ON S.ID = V.ID_PROYECTO_SERVICIO' + NCHAR(10) + N'                OUTER APPLY (SELECT TOP 1 ISNULL(VC.HORAS_EJECUTADAS, VC.HORAS_PLANIFICADAS) AS H FROM dbo.VCT_PROYECTOS_VISITAS_CONSULTORES VC WITH(NOLOCK)' + NCHAR(10) + N'                             WHERE VC.ID_VISITA = D.ID_VISITA AND VC.ID_CONSULTOR = D.ID_CONSULTOR) VH' + NCHAR(10) + N'                OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM, UPPER(LEFT(LTRIM(ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),'''')),1) + LEFT(LTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''')),1)) AS INI FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                WHERE D.ID_ACCION = A.ID' + NCHAR(10) + N'                ORDER BY V.FECHA_DESDE, D.ID' + NCHAR(10) + N'                FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), ''''), ''<div class="vct-plt-empty">Sin desarrollo cargado.</div>'')' + NCHAR(10) + N'            + CASE WHEN @PUEDE_PLAN = 1 THEN ''<div class="vct-pl-regs-ft"><button type="button" class="vct-btn vct-btn-new vct-btn-sm" data-pl-des-new="'' + CONVERT(VARCHAR(20), A.ID) + ''"><span data-vct-icon="plus"></span><span>Desarrollo</span></button></div>'' ELSE '''' END' + NCHAR(10) + N'            + ''</div>''' + NCHAR(10) + N'        FROM #PA A;' + NCHAR(10) + N'' + NCHAR(10) + N'        /* fila de accion (detalle): check de cumplida, responsable, vence, estado y menu Editar / Eliminar */';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' rhtml(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* xls_opt */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'+ ''<button type="button" class="vct-pl-opt" data-vct-pv-confirm="PV_PL_GENERAR" data-t11="BLANCO" data-id="0" data-msg="&iquest;Crear el plan en blanco?">''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'+ ''<button type="button" class="vct-pl-opt" data-pl-xls-open><b>B &middot; Subir Excel</b><span>Cap&iacute;tulos, &iacute;tems y sub&iacute;tems con fechas desde / hasta; vista previa antes de grabar</span></button>''' + NCHAR(10) + N'                      + ''<button type="button" class="vct-pl-opt" data-vct-pv-confirm="PV_PL_GENERAR" data-t11="BLANCO" data-id="0" data-msg="&iquest;Crear el plan en blanco?">''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' xls_opt(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* del_btn */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'+   CASE WHEN @PUEDE_PLAN = 1 AND @PL_CARGA_ABIERTA = 1 THEN ''<button type="button" class="vct-btn vct-btn-new vct-btn-sm" data-vct-pv-confirm="PV_PL_CERRAR"';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'+   CASE WHEN @PUEDE_PLAN = 1 AND @PL_CARGA_ABIERTA = 1 AND @PL_DES_N = 0 THEN ''<button type="button" class="vct-btn vct-btn-new vct-btn-sm vct-pl-del" data-vct-pv-confirm="PV_PL_BORRAR" data-id="0" data-nombre="Se eliminan el plan, sus &iacute;tems y sus acciones. Despu&eacute;s se puede volver a cargar (plan base, Excel o en blanco)."><span data-vct-icon="trash"></span><span>Eliminar plan</span></button>'' ELSE '''' END' + NCHAR(10) + N'            +   CASE WHEN @PUEDE_PLAN = 1 AND @PL_CARGA_ABIERTA = 1 THEN ''<button type="button" class="vct-btn vct-btn-new vct-btn-sm" data-vct-pv-confirm="PV_PL_CERRAR"';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' del_btn(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* ag_row */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'SELECT ''<tr data-vct-row data-pv-agg="'' + LOWER(A.T) + ''"';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'SELECT ''<tr data-vct-row data-pv-agw-row="'' + CONVERT(VARCHAR(20), A.ID) + ''" data-pv-agg="'' + LOWER(A.T) + ''"';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' ag_row(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* ag_menu */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'+ CASE WHEN @AG_PUEDE = 1 AND A.DESDE >= @HOY AND A.REG = 0 THEN' + NCHAR(10) + N'                    ''<button type="button" class="vct-row-menu-trigger" data-vctdg-rowmenu aria-label="Acciones" title="Acciones"><span class="vct-row-menu-dots" aria-hidden="true">&#8942;</span></button>''' + NCHAR(10) + N'                  + ''<div class="vctdg-rowmenu-items" hidden>''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'+ ''<button type="button" class="vct-row-menu-trigger" data-vctdg-rowmenu aria-label="Acciones" title="Acciones"><span class="vct-row-menu-dots" aria-hidden="true">&#8942;</span></button>'' + ''<div class="vctdg-rowmenu-items" hidden>''   /* PL_DES_V1 */' + NCHAR(10) + N'             + ''<button type="button" class="vct-pv-menu-btn" data-pv-agw-open="'' + CONVERT(VARCHAR(20), A.ID) + ''"><span data-vct-icon="eye"></span><span>Trabajo de la visita</span></button>''' + NCHAR(10) + N'             + CASE WHEN @AG_PUEDE = 1 AND A.DESDE >= @HOY AND A.REG = 0 THEN ''''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' ag_menu(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* ag_menu2 */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'+   ''<span data-vct-icon="trash"></span><span>Eliminar</span></button></div>''' + NCHAR(10) + N'               ELSE '''' END';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'+   ''<span data-vct-icon="trash"></span><span>Eliminar</span></button>''' + NCHAR(10) + N'               ELSE '''' END + ''</div>''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' ag_menu2(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* modals */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'/* accion del proyecto (pestania Acciones, AC_PESTANIA_V1): mismo modelo de la accion del plan, sin item */';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'/* ======================= PL_DES_V1: modales de desarrollo, plan desde Excel y trabajo de la visita ======================= */' + NCHAR(10) + N'    DECLARE @PL_DESM VARCHAR(MAX) = '''', @PL_XLSM VARCHAR(MAX) = '''', @AG_WM VARCHAR(MAX) = '''', @DS_VIS_L VARCHAR(MAX) = '''', @AGW VARCHAR(MAX) = '''';' + NCHAR(10) + N'    IF @PUEDE_PLAN = 1 AND @PLN IS NOT NULL' + NCHAR(10) + N'    BEGIN' + NCHAR(10) + N'        /* visitas del proyecto por consultor: "visita:consultor|desde|hasta|C/P|servicio|iniciales|consultor|horas|horas en desarrollos|propia" */' + NCHAR(10) + N'        SELECT @DS_VIS_L = ISNULL(STUFF((' + NCHAR(10) + N'            SELECT '';'' + CONVERT(VARCHAR(20), V.ID) + '':'' + CONVERT(VARCHAR(20), VC.ID_CONSULTOR)' + NCHAR(10) + N'                 + ''|'' + CONVERT(VARCHAR(10), V.FECHA_DESDE, 120) + ''|'' + CONVERT(VARCHAR(10), ISNULL(V.FECHA_HASTA, V.FECHA_DESDE), 120)' + NCHAR(10) + N'                 + ''|'' + CASE WHEN UPPER(LTRIM(RTRIM(ISNULL(V.ESTADO,'''')))) = ''CONFIRMADO'' THEN ''C'' ELSE ''P'' END' + NCHAR(10) + N'                 + ''|'' + REPLACE(REPLACE(ISNULL(CASE WHEN ISNULL(S.NOMBRE,'''') <> '''' THEN S.NOMBRE ELSE ISNULL(S.DES,'''') END, ''''), ''|'', ''/''), '';'', '','')' + NCHAR(10) + N'                 + ''|'' + ISNULL(Y.INI, '''') + ''|'' + REPLACE(REPLACE(ISNULL(Y.NOM, ''''), ''|'', ''/''), '';'', '','')' + NCHAR(10) + N'                 + ''|'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)))), ''.0'', '''')' + NCHAR(10) + N'                 + ''|'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(U.H, 0))), ''.0'', '''')' + NCHAR(10) + N'                 + ''|'' + CASE WHEN VC.ID_CONSULTOR = @CONS_U THEN ''1'' ELSE ''0'' END' + NCHAR(10) + N'            FROM dbo.VCT_PROYECTOS_VISITAS V WITH(NOLOCK)' + NCHAR(10) + N'            INNER JOIN dbo.VCT_PROYECTOS_VISITAS_CONSULTORES VC WITH(NOLOCK) ON VC.ID_VISITA = V.ID' + NCHAR(10) + N'            LEFT JOIN #SV S ON S.ID = V.ID_PROYECTO_SERVICIO' + NCHAR(10) + N'            OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM, UPPER(LEFT(LTRIM(ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),'''')),1) + LEFT(LTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''')),1)) AS INI FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = VC.ID_CONSULTOR) Y' + NCHAR(10) + N'            OUTER APPLY (SELECT SUM(D.HORAS) AS H FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                         WHERE D.ID_VISITA = V.ID AND D.ID_CONSULTOR = VC.ID_CONSULTOR AND D.TIPO = ''REALIZADO'') U' + NCHAR(10) + N'            WHERE V.ID_PROYECTO = @ID_PROYECTO AND UPPER(LTRIM(RTRIM(ISNULL(V.ESTADO,'''')))) NOT IN (''CANCELADO'',''ANULADO'')' + NCHAR(10) + N'            ORDER BY V.FECHA_DESDE, V.ID, VC.ID' + NCHAR(10) + N'            FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), 1, 1, ''''), '''');' + NCHAR(10) + N'        SET @PL_DESM = CONVERT(VARCHAR(MAX), '''')' + NCHAR(10) + N'            + ''<div class="vct-modal vct-form-shell vct-pv-modal vct-pv-w-xl vct-pv-desm" data-vct-component="modal" data-vct-pv-modal="des"''' + NCHAR(10) + N'            + '' data-pv-des-hoy="'' + CONVERT(VARCHAR(10), @HOY, 120) + ''" data-pv-des-vis="'' + REPLACE(REPLACE(REPLACE(REPLACE(@DS_VIS_L,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">''' + NCHAR(10) + N'            + ''<div class="vct-modal-backdrop" data-vct-pv-close></div><div class="vct-modal-dialog">''' + NCHAR(10) + N'            + ''<div class="vct-modal-header vct-form-header"><div class="vct-form-header-accent"></div><div class="vct-form-header-icon"><span data-vct-icon="edit"></span></div>''' + NCHAR(10) + N'            + ''<div class="vct-form-header-copy"><h3 class="vct-modal-title" data-pv-des-mtitle>Desarrollo de la acci&oacute;n</h3><p class="vct-modal-subtitle">Proyecto ('' + @E_COD + '') &middot; '' + @E_CLI + ''</p></div>''' + NCHAR(10) + N'            + ''<button type="button" class="vct-form-close" data-vct-pv-close aria-label="Cerrar">&times;</button></div>''' + NCHAR(10) + N'            + ''<div class="vct-modal-body vct-form-body"><div class="vct-validation-box" data-vct-pv-error style="display:none;"></div><div class="vct-form-grid">''' + NCHAR(10) + N'            + ''<div class="vct-field vct-col-12"><label class="vct-label">Acci&oacute;n</label><input type="text" class="vct-input" readonly data-pv-des-acc></div>''' + NCHAR(10) + N'            + ''<div class="vct-field vct-col-12"><label class="vct-label">Tipo</label><div class="vct-pv-des-tipo" data-pv-des-tipo>''' + NCHAR(10) + N'            +   ''<button type="button" class="is-r" data-v="R">Realizado &middot; visita confirmada</button><button type="button" class="is-p" data-v="P">Planificado &middot; pr&oacute;xima visita</button></div>''' + NCHAR(10) + N'            +   ''<div class="vct-help" data-pv-des-thelp></div></div>''' + NCHAR(10) + N'            + ''<div class="vct-field vct-col-12"><label class="vct-label">Visita <span class="vct-req">*</span></label><div class="vct-pv-des-vis" data-pv-des-cards></div></div>''' + NCHAR(10) + N'            + ''<div class="vct-field vct-col-3" data-pv-des-hw><label class="vct-label">Horas <span class="vct-req">*</span></label>''' + NCHAR(10) + N'            +   ''<input type="number" class="vct-input" min="0.5" step="0.5" data-pv-des-f="hrs"><div class="vct-help" data-pv-des-hhelp></div></div>''' + NCHAR(10) + N'            + ''<div class="vct-field vct-col-9" data-pv-des-tw><label class="vct-label">T&iacute;tulo breve <span class="vct-req">*</span></label>''' + NCHAR(10) + N'            +   ''<input type="text" class="vct-input" maxlength="300" data-pv-des-f="tit"></div>''' + NCHAR(10) + N'            + ''<div class="vct-field vct-col-12"><label class="vct-label"><span data-pv-des-dlbl>Desarrollo</span> <span class="vct-req" data-pv-des-dreq>*</span></label>''' + NCHAR(10) + N'            +   ''<textarea class="vct-textarea" rows="4" maxlength="4000" data-pv-des-f="des"></textarea></div>''' + NCHAR(10) + N'            + ''<div class="vct-field vct-col-12"><label class="vct-label">Pr&oacute;ximo paso</label>''' + NCHAR(10) + N'            +   ''<input type="text" class="vct-input" maxlength="1000" placeholder="Opcional: lo que queda para la pr&oacute;xima visita" data-pv-des-f="prox"></div>''' + NCHAR(10) + N'            + ''<div class="vct-field vct-col-12"><div class="vct-help">Las horas de desarrollo no son horas ejecutadas: las ejecutadas del proyecto salen de las visitas. ''' + NCHAR(10) + N'            +   ''La suma de los desarrollos de un consultor en una visita no puede superar sus horas en esa visita; lo que no se detalla queda como dato de informe.</div></div>''' + NCHAR(10) + N'            + ''</div></div>''' + NCHAR(10) + N'            + ''<div class="vct-modal-footer vct-form-footer"><button type="button" class="vct-btn vct-btn-secondary" data-vct-pv-close><span>Cancelar</span></button>''' + NCHAR(10) + N'            + ''<button type="button" class="vct-btn vct-btn-primary" data-pv-des-save><span data-vct-icon="save"></span><span>Guardar desarrollo</span></button></div></div></div>'';' + NCHAR(10) + N'    END;' + NCHAR(10) + N'    IF @PUEDE_PLAN = 1 AND @PLN IS NULL AND @PLN_TIENE_CO = 1 AND @EST_COD = ''ENCURSO''' + NCHAR(10) + N'        SET @PL_XLSM = CONVERT(VARCHAR(MAX), '''')' + NCHAR(10) + N'            + ''<div class="vct-modal vct-form-shell vct-pv-modal vct-pv-w-xl vct-pv-xlsm" data-vct-component="modal" data-vct-pv-modal="xls"''' + NCHAR(10) + N'            + '' data-pv-xls-ini="'' + ISNULL(CONVERT(VARCHAR(10), ISNULL(@F_INI_REAL, @F_INI), 120), '''') + ''" data-pv-xls-fin="'' + ISNULL(CONVERT(VARCHAR(10), @F_FIN, 120), '''') + ''"''' + NCHAR(10) + N'            + '' data-pv-xls-cod="'' + REPLACE(@E_COD, ''"'', '''') + ''">''' + NCHAR(10) + N'            + ''<div class="vct-modal-backdrop" data-vct-pv-close></div><div class="vct-modal-dialog">''' + NCHAR(10) + N'            + ''<div class="vct-modal-header vct-form-header"><div class="vct-form-header-accent"></div><div class="vct-form-header-icon"><span data-vct-icon="file-spreadsheet"></span></div>''' + NCHAR(10) + N'            + ''<div class="vct-form-header-copy"><h3 class="vct-modal-title">Cargar plan desde Excel</h3><p class="vct-modal-subtitle">Proyecto ('' + @E_COD + '') &middot; '' + @E_CLI' + NCHAR(10) + N'            +   '' &middot; '' + ISNULL(CONVERT(VARCHAR(10), ISNULL(@F_INI_REAL, @F_INI), 103), ''-'') + '' al '' + ISNULL(CONVERT(VARCHAR(10), @F_FIN, 103), ''-'') + ''</p></div>''' + NCHAR(10) + N'            + ''<button type="button" class="vct-form-close" data-vct-pv-close aria-label="Cerrar">&times;</button></div>''' + NCHAR(10) + N'            + ''<div class="vct-modal-body vct-form-body"><div class="vct-validation-box" data-vct-pv-error style="display:none;"></div><div class="vct-form-grid">''' + NCHAR(10) + N'            + ''<div class="vct-field vct-col-12"><div class="vct-pv-xls-drop" data-pv-xls-drop><span class="vct-pv-xls-ic"><span data-vct-icon="download"></span></span>''' + NCHAR(10) + N'            +   ''<span class="vct-pv-xls-tx"><b>Arrastr&aacute; el archivo o elegilo</b><small>.xlsx o .csv &middot; se lee la primera hoja &middot; columnas C&oacute;digo, T&iacute;tulo, Fecha desde y Fecha hasta; el resto se ignora y el archivo no se guarda.</small></span>''' + NCHAR(10) + N'            +   ''<button type="button" class="vct-btn vct-btn-secondary vct-btn-sm" data-pv-xls-tpl><span data-vct-icon="download"></span><span>Plantilla</span></button>''' + NCHAR(10) + N'            +   ''<button type="button" class="vct-btn vct-btn-new vct-btn-sm" data-pv-xls-pick><span data-vct-icon="file-text"></span><span>Elegir archivo</span></button>''' + NCHAR(10) + N'            +   ''<input type="file" accept=".xlsx,.csv" hidden data-pv-xls-file></div>''' + NCHAR(10) + N'            +   ''<div class="vct-help">El nivel sale del c&oacute;digo: 4 cap&iacute;tulo, 4.1 &iacute;tem, 4.1.1 sub&iacute;tem. Las fechas del cap&iacute;tulo no hacen falta (se calculan con sus &iacute;tems). ''' + NCHAR(10) + N'            +   ''Fechas dentro del proyecto y cada sub&iacute;tem dentro de su &iacute;tem.</div></div>''' + NCHAR(10) + N'            + ''<div class="vct-field vct-col-12" data-pv-xls-prev></div>''' + NCHAR(10) + N'            + ''</div></div>''' + NCHAR(10) + N'            + ''<div class="vct-modal-footer vct-form-footer"><button type="button" class="vct-btn vct-btn-secondary" data-vct-pv-close><span>Cancelar</span></button>''' + NCHAR(10) + N'            + ''<button type="button" class="vct-btn vct-btn-primary" data-pv-xls-save disabled><span data-vct-icon="save"></span><span data-pv-xls-savelbl>Grabar plan</span></button></div></div></div>'';' + NCHAR(10) + N'' + NCHAR(10) + N'    /* trabajo de cada visita de la agenda (lo trabajado y lo planificado en la visita) */' + NCHAR(10) + N'    IF @AG_NV > 0' + NCHAR(10) + N'    BEGIN' + NCHAR(10) + N'        SELECT @AGW = ISNULL((' + NCHAR(10) + N'            SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw" data-pv-agw="'' + CONVERT(VARCHAR(20), A.ID) + ''" hidden''' + NCHAR(10) + N'                 + '' data-x="'' + REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(A.INST + CASE WHEN A.CONS_TXT <> '''' THEN '' - '' + A.CONS_TXT ELSE '''' END,''\'',''/''),''"'',''''''''),CHAR(10),'' ''),CHAR(13),'' ''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''"''' + NCHAR(10) + N'                 + '' data-d1="'' + CONVERT(VARCHAR(10), A.DESDE, 120) + ''" data-d2="'' + CONVERT(VARCHAR(10), A.HASTA, 120) + ''"''' + NCHAR(10) + N'                 + '' data-tit="Visita del '' + CONVERT(VARCHAR(10), A.DESDE, 103) + CASE WHEN A.HASTA > A.DESDE THEN '' al '' + CONVERT(VARCHAR(10), A.HASTA, 103) ELSE '''' END + ''"''' + NCHAR(10) + N'                 + '' data-sub="'' + REPLACE(REPLACE(REPLACE(REPLACE(A.INST + '' - '' + CASE A.SIT WHEN ''e'' THEN ''Ejecutada'' WHEN ''c'' THEN ''Confirmada'' ELSE ''Pendiente'' END + CASE WHEN A.CONS_TXT <> '''' THEN '' - '' + A.CONS_TXT ELSE '''' END,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-k"><div><small>Horas de la visita</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), A.HT)), ''.0'', '''') + '' h</b></div>''' + NCHAR(10) + N'                 + ''<div><small>Volcadas en desarrollos</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(R.H, 0))), ''.0'', '''') + '' h</b></div>''' + NCHAR(10) + N'                 + ''<div><small>Sin detallar (informe)</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), CASE WHEN A.HT > ISNULL(R.H, 0) THEN A.HT - ISNULL(R.H, 0) ELSE 0 END)), ''.0'', '''') + '' h</b></div>''' + NCHAR(10) + N'                 + ''<div><small>Planificados</small><b>'' + CONVERT(VARCHAR(10), ISNULL(R.NP, 0)) + ''</b></div></div>''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-cols">''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-col"><div class="vct-pv-agw-h">Trabajado en la visita<span class="vct-360-badge is-active">'' + CONVERT(VARCHAR(10), ISNULL(R.NR, 0)) + '' &middot; '' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(R.H, 0))), ''.0'', '''') + '' h</span></div>''' + NCHAR(10) + N'                 + ISNULL(NULLIF((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it"><div>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN ''<span class="vct-pl-code">'' + REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span> '' ELSE '''' END' + NCHAR(10) + N'                                      + ''<small>'' + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</small><b>'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<p>'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 600),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</p>'' ELSE '''' END' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.PROXIMO_PASO, '''') <> '''' THEN ''<em>Pr&oacute;ximo: '' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</em>'' ELSE '''' END' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-who">'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span></div><span class="vct-pv-agw-hs">'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(D.HORAS, 0))), ''.0'', '''') + '' h</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE D.ID_VISITA = A.ID AND D.TIPO = ''REALIZADO'' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), ''''), ''<div class="vct-plt-empty">Sin desarrollos realizados en esta visita.</div>'')' + NCHAR(10) + N'                 + ''</div>''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-col"><div class="vct-pv-agw-h">Planificado para la visita<span class="vct-360-badge is-planned">'' + CONVERT(VARCHAR(10), ISNULL(R.NP, 0)) + ''</span></div>''' + NCHAR(10) + N'                 + ISNULL(NULLIF((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it"><div>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN ''<span class="vct-pl-code">'' + REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span> '' ELSE '''' END' + NCHAR(10) + N'                                      + ''<small>'' + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</small><b>'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<p>'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 600),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</p>'' ELSE '''' END' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-who">'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span></div><span class="vct-pv-agw-hs">&ndash;</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE D.ID_VISITA = A.ID AND D.TIPO = ''PLANIFICADO'' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), ''''), ''<div class="vct-plt-empty">Nada planificado para esta visita.</div>'')' + NCHAR(10) + N'                 + ''</div></div></div>''' + NCHAR(10) + N'            FROM #AGV A' + NCHAR(10) + N'            OUTER APPLY (SELECT SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN ISNULL(D.HORAS, 0) ELSE 0 END) AS H,' + NCHAR(10) + N'                                SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN 1 ELSE 0 END) AS NR,' + NCHAR(10) + N'                                SUM(CASE WHEN D.TIPO = ''PLANIFICADO'' THEN 1 ELSE 0 END) AS NP' + NCHAR(10) + N'                         FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_VISITA = A.ID) R' + NCHAR(10) + N'            ORDER BY A.DESDE, A.ID' + NCHAR(10) + N'            FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''');' + NCHAR(10) + N'        SET @AG_WM = CONVERT(VARCHAR(MAX), '''')' + NCHAR(10) + N'            + ''<div class="vct-modal vct-form-shell vct-pv-modal vct-pv-w-xl vct-pv-agwm" data-vct-component="modal" data-vct-pv-modal="agw">''' + NCHAR(10) + N'            + ''<div class="vct-modal-backdrop" data-vct-pv-close></div><div class="vct-modal-dialog">''' + NCHAR(10) + N'            + ''<div class="vct-modal-header vct-form-header"><div class="vct-form-header-accent"></div><div class="vct-form-header-icon"><span data-vct-icon="calendar"></span></div>''' + NCHAR(10) + N'            + ''<div class="vct-form-header-copy"><h3 class="vct-modal-title" data-pv-agw-title>Trabajo de la visita</h3><p class="vct-modal-subtitle" data-pv-agw-sub></p></div>''' + NCHAR(10) + N'            + ''<button type="button" class="vct-form-close" data-vct-pv-close aria-label="Cerrar">&times;</button></div>''' + NCHAR(10) + N'            + ''<div class="vct-modal-body vct-form-body">'' + @AGW + ''</div>''' + NCHAR(10) + N'            + ''<div class="vct-modal-footer vct-form-footer"><button type="button" class="vct-btn vct-btn-secondary" data-vct-pv-close><span>Cerrar</span></button></div></div></div>'';' + NCHAR(10) + N'    END;' + NCHAR(10) + N'' + NCHAR(10) + N'    /* accion del proyecto (pestania Acciones, AC_PESTANIA_V1): mismo modelo de la accion del plan, sin item */';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' modals(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* out */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'+ @LZ_MODALS + @PL_MODALS + @AC_MODAL + @PE_MODAL + @AG_MODAL';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'+ @LZ_MODALS + @PL_MODALS + @AC_MODAL + @PE_MODAL + @AG_MODAL + @PL_DESM + @PL_XLSM + @AG_WM';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' out(' + CONVERT(NVARCHAR(10), @N) + N')';
    IF @F <> N''
        PRINT 'FALLO: no se encontraron en la definicion vigente los puntos:' + @F + '. No se cambio nada.';
    ELSE
    BEGIN
        SET @s = CHARINDEX(N'PROCEDURE', @D);
        SET @p = CASE WHEN @s > 40 THEN @s - 40 ELSE 1 END;
        IF CHARINDEX(N'CREATE', SUBSTRING(@D, @p, 40)) > 0 AND CHARINDEX(N'OR ALTER', SUBSTRING(@D, @p, 40)) = 0
            SET @D = STUFF(@D, @p + CHARINDEX(N'CREATE', SUBSTRING(@D, @p, 40)) - 1, 6, N'ALTER ');
        BEGIN TRY
            EXEC sys.sp_executesql @D;
            PRINT 'OK   VCT_MAIN_PROYECTO_V360 actualizado (PL_DES_V1). Subir vct-proyecto-v360.css (v41) y vct-proyecto-v360.js (v33).';
        END TRY
        BEGIN CATCH
            PRINT 'FALLO al actualizar VCT_MAIN_PROYECTO_V360 (no se cambio): ' + ERROR_MESSAGE() + ' (linea ' + CONVERT(VARCHAR(10), ERROR_LINE()) + ')';
        END CATCH;
    END;
END;
GO
